package org.circus.core;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;

/** Actual Windows GDI audit for the d474DC2 API leaf; original EXE never runs.
 *Saved mono/metrics feed a separate selected-native-instruction crosscheck. */
public final class Dc2GdiGlyphAudit {
    private static int checks;
    private static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static String q(String value){return"\""+value.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";}
    private static String hex(byte[] b){return q(Binary.hex(b));}
    private static int le(byte[] b,int at){return(b[at]&255)|(b[at+1]&255)<<8|(b[at+2]&255)<<16|b[at+3]<<24;}
    private static void clearCache(Dc2GlyphMemory memory)throws IOException{for(int at=Dc2GlyphMemory.CACHE;at<Dc2GlyphMemory.CACHE_END;at++)memory.writeByte(at,0);}
    private static final class Counting implements Dc2GlyphCache.Provider {
        final Dc2GdiGlyph actual;final Dc2GlyphMemory memory;int calls;boolean fence,record;final List<String> recorded=new ArrayList<>();
        Counting(Dc2GdiGlyph actual,Dc2GlyphMemory memory){this.actual=actual;this.memory=memory;}
        public Pc1GlyphRaster.Outline outline(Dc2GlyphCache.Source source,int size)throws IOException{calls++;if(memory.busy())try{memory.save(new DataOutputStream(new ByteArrayOutputStream()));}catch(IOException expected){fence=true;}Pc1GlyphRaster.Outline result=actual.outline(source,size);if(record)recorded.add("{\"required\":"+actual.lastRequiredByteCount()+",\"size\":"+size+",\"character\":"+Dc2GlyphCache.characterCode(source)+",\"selected\":"+actual.snapshot().selectedSize+",\"metrics\":"+hex(memory.fontState.textMetrics())+",\"width\":"+result.width+",\"height\":"+result.height+",\"ox\":"+result.originX+",\"oy\":"+result.originY+",\"cell_x\":"+result.cellIncX+",\"cell_y\":"+result.cellIncY+",\"mono\":"+hex(result.monoBytes())+"}");return result;}
        public byte[] saveFontContext()throws IOException{return actual.saveFontContext();}
        public void restoreFontContext(byte[] bytes)throws IOException{actual.restoreFontContext(bytes);}
    }
    public static void main(String[] args)throws Exception{
        if(args.length!=2)throw new IOException("Dc2GdiGlyphAudit library output-directory");Path out=Paths.get(args[1]).toAbsolutePath();Files.createDirectories(out);List<String> rows=new ArrayList<>();
        final byte[] palette=new byte[256],shade={8,0,0,0},literal={(byte)0xa1,(byte)0xa4,0,0};
        for(int n=0;n<64;n++){palette[n*4]=(byte)(n*19+11);palette[n*4+1]=(byte)(n*31+17);palette[n*4+2]=(byte)(n*7+3);}
        Dc2GlyphMemory memory=new Dc2GlyphMemory(new NativeGlyphCache.Memory(){public int readByte(int address)throws IOException{if(address>=0x451720&&address<0x451820)return palette[address-0x451720]&255;if(address>=0x473f84&&address<0x473f88)return shade[address-0x473f84]&255;if(address>=0x45e9a4&&address<0x45e9a8)return literal[address-0x45e9a4]&255;throw new IOException("ActualGDI audit unowned neighbor"+Integer.toHexString(address));}public void writeByte(int address,int value)throws IOException{throw new IOException("ActualGDI audit external writes unowned");}});
        try(Dc2GdiGlyph actual=new Dc2GdiGlyph(Paths.get(args[0]),memory.fontState)){
            Counting provider=new Counting(actual,memory);String environment=actual.environment();Dc2GdiGlyph.State initial=actual.snapshot();check(initial.selectedSize==28&&memory.fontState.requestedSize()==0&&le(memory.fontState.textMetrics(),4)==0,"Initial selected28 differs from BSS requested0/ascent0");
            int[] sizes={12,16,17,22,28,32,40,28,19};byte[][] raw={{65,0},{(byte)0xa1,(byte)0xa4,0},{(byte)0xb2,(byte)0xe2,0},{66,0},{(byte)0xd6,(byte)0xd0,0},{67,0},{(byte)0xce,(byte)0xc4,0},{65,0},{66,0}};
            for(int n=0;n<sizes.length;n++){
                int size=sizes[n];if(size==19)memory.fontState.requestedSize(19);clearCache(memory);byte[] beforeMetrics=memory.fontState.textMetrics(),beforeScratch=actual.scratch();int beforeRequested=memory.fontState.requestedSize(),beforeSelected=actual.snapshot().selectedSize;
                Pc1GlyphRaster.Outline glyph=provider.outline(Dc2GlyphService.known(raw[n],0),size);NativeGlyphProjection.project(memory,Dc2GlyphMemory.CACHE+8,size,Dc2GlyphMemory.TEXT_METRICS+4,glyph);int selected=actual.snapshot().selectedSize;
                check(memory.fontState.requestedSize()==size,"Canonical requested field updated");check(selected==(size==19?beforeSelected:Dc2GlyphCache.selectedFontSize(size)),"Actual DC2 font fallback16 including32");check(glyph.monoBytes().length==19200&&actual.lastRequiredByteCount()<=19200,"Actual fullknown mono scratch independent from APIrequired length");
                rows.add("{\"required\":"+actual.lastRequiredByteCount()+",\"size\":"+size+",\"raw\":"+hex(raw[n])+",\"before_requested\":"+beforeRequested+",\"before_selected\":"+beforeSelected+",\"before_metrics\":"+hex(beforeMetrics)+",\"before_scratch\":"+hex(beforeScratch)+",\"selected\":"+selected+",\"metrics\":"+hex(memory.fontState.textMetrics())+",\"ascent\":"+glyph.ascent+",\"width\":"+glyph.width+",\"height\":"+glyph.height+",\"ox\":"+glyph.originX+",\"oy\":"+glyph.originY+",\"cell_x\":"+glyph.cellIncX+",\"cell_y\":"+glyph.cellIncY+",\"mono\":"+hex(glyph.monoBytes())+",\"java_cache_metrics_sha256\":"+q(Binary.sha256(memory.ownedBytes(Dc2GlyphMemory.CACHE,Dc2GlyphMemory.TEXT_METRICS+56-Dc2GlyphMemory.CACHE)))+",\"java_scratch_sha256\":"+q(Binary.sha256(actual.scratch()))+"}");
            }
            Dc2GlyphCache cache=new Dc2GlyphCache(memory);clearCache(memory);byte[] a={65,0};NativeGlyphCache.Lookup first=cache.lookup(Dc2GlyphService.known(a,0),28,provider);int misses=provider.calls;memory.fontState.requestedSize(19);byte[] metrics=memory.fontState.textMetrics(),scratch=actual.scratch();NativeGlyphCache.Lookup hit=cache.lookup(Dc2GlyphService.known(a,0),28,provider);check(!first.hit&&hit.hit&&hit.address==first.address&&provider.calls==misses,"Cache hit makes no GDI call");check(memory.fontState.requestedSize()==19&&Arrays.equals(metrics,memory.fontState.textMetrics())&&Arrays.equals(scratch,actual.scratch()),"Hit preserves raw requested/metrics and independent native scratch");
            byte[] saved=actual.saveFontContext();int coreRequested=memory.fontState.requestedSize();byte[] coreMetrics=memory.fontState.textMetrics();provider.outline(Dc2GlyphService.known(new byte[]{67,0},0),40);memory.fontState.requestedSize(-7);actual.restoreFontContext(saved);check(memory.fontState.requestedSize()==-7,"Physicalfont restore does not roll back borrowed core requested");memory.fontState.requestedSize(coreRequested);memory.fontState.textMetrics(coreMetrics);check(actual.snapshot().selectedSize==28,"Physical font restore resumes actual selected font");
            Dc2GdiGlyph.State state=actual.snapshot();ByteArrayOutputStream bad=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(bad);data.writeInt(0x44324732);data.writeInt(state.selectedSize);data.writeInt(state.ansiCodePage);data.writeUTF(state.faceName);data.writeUTF(String.join("",Collections.nCopies(64,"0")));data.write(state.scratchBytes());boolean rejected=false;try{actual.restoreFontContext(bad.toByteArray());}catch(IOException exact){rejected=true;}check(rejected&&actual.snapshot().fontIdentity.equals(state.fontIdentity),"Different font identity rejected transactionally");
            Dc2Compositor compositor=new Dc2Compositor(NativeRgbImage.zeroed(200,100));compositor.fill(0,0,200,100,0x24343a);compositor.resetDirty();Dc2GlyphService service=new Dc2GlyphService(memory,cache,provider,compositor);int[][] records={{10,10,38,38,28,0x81,0,65},{45,10,73,38,28,0x80,0,0xd0d6},{85,10,97,22,12,0x82,0,0x4581},{120,10,148,38,28,0x4ac3,3,66}};for(int n=0;n<records.length;n++)for(int k=0;k<8;k++)memory.write(Dc2GlyphMemory.JOURNAL+n*32+k*4,records[n][k]);memory.write(Dc2GlyphMemory.COUNT,records.length);
            ByteArrayOutputStream beforeWire=new ByteArrayOutputStream();memory.save(new DataOutputStream(beforeWire));Files.write(out.resolve("before-journal-d2gm.bin"),beforeWire.toByteArray());Dc2GdiGlyph.State beforeJournal=actual.snapshot();provider.record=true;service.drawJournal(0);provider.record=false;check(provider.fence,"Real GDI cache miss rejects snapshot inside callback");Pc1Raster.Rect dirty=compositor.rawDirty();check(dirty.right>dirty.left&&dirty.bottom>dirty.top,"Actual glyph journal mutates same persistent image/dirty owner");NativeRgbImage pixels=compositor.front();BufferedImage png=new BufferedImage(pixels.width,pixels.height,BufferedImage.TYPE_INT_RGB);for(int y=0;y<pixels.height;y++)for(int x=0;x<pixels.width;x++)png.setRGB(x,y,pixels.rgb(x,y));Path pngPath=out.resolve("dc2-actual-gdi.png");ImageIO.write(png,"PNG",pngPath.toFile());ByteArrayOutputStream afterWire=new ByteArrayOutputStream();memory.save(new DataOutputStream(afterWire));Files.write(out.resolve("after-journal-d2gm.bin"),afterWire.toByteArray());
            String journal="{\"width\":200,\"height\":100,\"initial_rgb\":2372666,\"palette\":"+hex(palette)+",\"before_selected\":"+beforeJournal.selectedSize+",\"before_scratch\":"+hex(beforeJournal.scratchBytes())+",\"after_scratch_sha256\":"+q(Binary.sha256(actual.scratch()))+",\"after_selected\":"+actual.snapshot().selectedSize+",\"pixel_sha256\":"+q(Binary.sha256(pixels.bgr24()))+",\"dirty\":["+dirty.left+","+dirty.top+","+dirty.right+","+dirty.bottom+"],\"api\":["+String.join(",",provider.recorded)+"]}";Files.write(out.resolve("journal-native-input.json"),journal.getBytes("UTF-8"));
            ByteArrayOutputStream fontWire=new ByteArrayOutputStream();service.saveFontContext(new DataOutputStream(fontWire));byte[] fullContext=fontWire.toByteArray();service.restoreFontContext(new DataInputStream(new ByteArrayInputStream(fullContext)));ByteArrayOutputStream restoredWire=new ByteArrayOutputStream();service.saveFontContext(new DataOutputStream(restoredWire));check(Arrays.equals(fullContext,restoredWire.toByteArray()),"Provider physicalfont/scratch packet exactly restores with same actual environment");
            String result="{\"checks\":"+checks+",\"environment\":"+q(environment)+",\"actual_font\":"+q(state.faceName)+",\"ansi_code_page\":"+state.ansiCodePage+",\"pixel_sha256\":"+q(Binary.sha256(pixels.bgr24()))+",\"png\":"+q(pngPath.toString())+",\"scope\":\"Own JNI calls Windows GDI only; original EXE never runs. Recorded actual payloads require separate private native-kernel crosscheck.\"}";Files.write(out.resolve("result.json"),result.getBytes("UTF-8"));Files.write(out.resolve("gdi-vectors.json"),("["+String.join(",\n",rows)+"]").getBytes("UTF-8"));System.out.println("DC2 actual GDI assertions: "+checks+"; "+environment);
        }
    }
}
